source='''from collections import Counter, deque, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            top = min(y for y, x in cells)
            bottom = max(y for y, x in cells)
            left = min(x for y, x in cells)
            right = max(x for y, x in cells)
            if bottom - top < 2 or right - left < 2:
                continue
            border = [grid[y][x] for y, x in cells
                      if y in (top, bottom) or x in (left, right)]
            inner = [grid[y][x] for y in range(top + 1, bottom)
                     for x in range(left + 1, right)]
            border_color = Counter(border).most_common(1)[0][0]
            core_color = Counter(inner).most_common(1)[0][0]
            if core_color == border_color:
                continue
            boxes.append({"top": top, "bottom": bottom, "left": left, "right": right,
                          "color": core_color})

    if not boxes:
        return out
    counts = Counter(box["color"] for box in boxes)
    background_core = counts.most_common(1)[0][0]
    special_colors = set(counts) - {background_core}

    def paint(y, x, color):
        if out[y][x] == 0:
            out[y][x] = color

    for color in special_colors:
        markers = [box for box in boxes if box["color"] == color]
        rows = defaultdict(list)
        cols = defaultdict(list)
        for box in markers:
            rows[(box["top"], box["bottom"])].append(box)
            cols[(box["left"], box["right"])].append(box)

        for (top, bottom), group in rows.items():
            if len(group) < 2:
                continue
            group.sort(key=lambda b: b["left"])
            lo, hi = group[0]["left"], group[-1]["right"]
            tiles = sorted((b for b in boxes if b["top"] == top and b["bottom"] == bottom
                            and b["right"] >= lo and b["left"] <= hi), key=lambda b: b["left"])
            core_rows = range(top + 1, bottom)
            for a, b in zip(tiles, tiles[1:]):
                if a["left"] < hi and b["right"] > lo:
                    for x in range(a["right"] + 1, b["left"]):
                        for y in core_rows:
                            paint(y, x, color)

        for (left, right), group in cols.items():
            if len(group) < 2:
                continue
            group.sort(key=lambda b: b["top"])
            lo, hi = group[0]["top"], group[-1]["bottom"]
            tiles = sorted((b for b in boxes if b["left"] == left and b["right"] == right
                            and b["bottom"] >= lo and b["top"] <= hi), key=lambda b: b["top"])
            core_cols = range(left + 1, right)
            for a, b in zip(tiles, tiles[1:]):
                if a["top"] < hi and b["bottom"] > lo:
                    for y in range(a["bottom"] + 1, b["top"]):
                        for x in core_cols:
                            paint(y, x, color)
    return out
